import { Bar, BarChart, CartesianGrid, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { MapPinned } from 'lucide-react';
import topDropoffs from '@/data/top_dropoffs.json';
import type { TopDropoffZone } from '@/types/charts';
import { axisTick, compactNumber, tooltipStyle } from './chartTheme';

/**
 * Top-10 drop-off zones — train.ipynb cell 8 (`df.groupby(dropoff).size().nlargest(10)`),
 * generated by scripts/generate_chart_data.py with human labels resolved from the shared
 * landmark dataset. Answers "what are the most common destinations".
 */
export function TopDropoffsChart() {
  const data = [...(topDropoffs as TopDropoffZone[])].sort((a, b) => b.rides - a.rides);

  return (
    <Card className="rounded-lg border">
      <CardHeader className="flex-row items-center gap-2 space-y-0 pb-3">
        <MapPinned className="h-5 w-5 text-muted-foreground" />
        <div>
          <CardTitle className="text-lg font-semibold">Top 10 Drop-off Zones</CardTitle>
          <CardDescription className="text-sm">Most common destinations</CardDescription>
        </div>
      </CardHeader>
      <CardContent>
        <ResponsiveContainer width="100%" height={320}>
          <BarChart
            data={data}
            layout="vertical"
            margin={{ top: 10, right: 20, left: 10, bottom: 0 }}
          >
            <CartesianGrid strokeDasharray="3 3" stroke="var(--border)" horizontal={false} />
            <XAxis
              type="number"
              tick={axisTick}
              axisLine={false}
              tickLine={false}
              tickFormatter={compactNumber}
            />
            <YAxis
              type="category"
              dataKey="label"
              tick={{ ...axisTick, fontSize: 11 }}
              axisLine={false}
              tickLine={false}
              width={130}
            />
            <Tooltip
              cursor={{ fill: 'var(--accent)' }}
              contentStyle={tooltipStyle}
              formatter={(value, name) => {
                if (name === 'avgFare') {
                  return [`$${Number(value ?? 0).toFixed(2)}`, 'Avg fare'] as [string, string];
                }
                return [
                  typeof value === 'number' ? value.toLocaleString() : String(value),
                  'Rides',
                ] as [string, string];
              }}
            />
            <Bar dataKey="rides" fill="var(--chart-1)" radius={[0, 4, 4, 0]} maxBarSize={18} />
          </BarChart>
        </ResponsiveContainer>
      </CardContent>
    </Card>
  );
}
